// In-flight transaction panel. Anything broadcast shows here until the chain
// says what happened, and survives reloads — the user always has a handle on
// money that is already moving.
import { el, replace } from '../dom.js'
import { chainById } from '../config.js'
import { loadPending, reconcile, prune, settle, forget } from '../pending.js'
import { prepareReplacement, signAndSend, client } from '../tx.js'
import { recordBroadcast } from '../pending.js'
import { safeLink } from './safelink.js'

const short = (h) => `${String(h).slice(0, 10)}…${String(h).slice(-6)}`
const age = (ms) => {
  const s = Math.floor((Date.now() - ms) / 1000)
  if (s < 60) return `${s}s`
  if (s < 3600) return `${Math.floor(s / 60)}m`
  return `${Math.floor(s / 3600)}h`
}

export function createPendingPanel(onChange) {
  const box = el('div')
  let busy = false

  async function replace_(row, mode) {
    if (busy) return
    busy = true
    try {
      const prep = await prepareReplacement(row, mode)
      const what = mode === 'cancel'
        ? `Cancel the transfer of ${row.asset}?\n\nThis sends a replacement at the same nonce (${prep.tx.nonce}) that does nothing. It only works if the original has not confirmed yet.`
        : `Speed up the transfer of ${row.asset}?\n\nRe-sends the same transaction at nonce ${prep.tx.nonce} with a higher fee (~${Number(prep.feeEstimate).toFixed(6)} ETH).`
      if (!confirm(what + '\n\nConfirm on the KeepKey when prompted.')) { busy = false; return }

      const hash = await signAndSend(row.accountIndex, prep)
      // The old hash is superseded: same nonce, so only one can ever confirm.
      forget(row.hash)
      recordBroadcast({
        hash, chainId: row.chainId, chainName: row.chainName,
        kind: mode === 'cancel' ? 'cancel' : row.kind,
        asset: mode === 'cancel' ? `cancel ${row.asset}` : row.asset,
        from: row.from, to: mode === 'cancel' ? row.from : row.to,
        nonce: prep.tx.nonce, account: row.account, accountIndex: row.accountIndex,
      })
      render(); onChange?.()

      const receipt = await client(row.chainId).waitForTransactionReceipt({ hash, timeout: 180_000 })
      settle(hash, receipt.status === 'success' ? 'success' : 'reverted', receipt.blockNumber)
      render(); onChange?.()
    } catch (e) {
      alert((mode === 'cancel' ? 'Cancel' : 'Speed up') + ' failed: ' + e.message)
    }
    busy = false
  }

  function render() {
    prune()
    const rows = loadPending()
    if (!rows.length) return replace(box)

    replace(box,
      el('h2', {}, `Transactions — ${rows.filter((r) => r.status === 'pending').length} in flight`),
      el('div', { class: 'prooflist' }, rows.map((row) => {
        const chain = chainById(row.chainId)
        const cls = row.status === 'pending' ? 'approw' : row.status === 'success' ? 'approw good' : 'approw danger'
        return el('div', { class: cls },
          el('div', { style: 'flex:1;min-width:0' },
            el('div', {}, el('b', {}, row.asset || row.kind || 'transaction'),
              row.status === 'pending' ? ` · pending ${age(row.at)}` :
              row.status === 'success' ? ' · confirmed' :
              row.status === 'reverted' ? ' · REVERTED on-chain' : ' · dropped from mempool'),
            el('div', { class: 'apsub' },
              `${row.chainName}`, row.nonce ? ` · nonce ${row.nonce}` : '', ' · ',
              safeLink(`${chain?.explorer}/tx/${row.hash}`, short(row.hash)))),
          row.status === 'pending'
            ? el('button', { class: 'ghost', onclick: () => replace_(row, 'speedup') }, 'Speed up')
            : null,
          row.status === 'pending'
            ? el('button', { class: 'danger', onclick: () => replace_(row, 'cancel') }, 'Cancel')
            : el('button', { class: 'ghost', onclick: () => { forget(row.hash); render() } }, 'Dismiss'))
      })))
  }

  // On load, ask the chain about anything we last saw as pending.
  reconcile(render).then(() => { render(); onChange?.() })
  setInterval(() => { if (!document.hidden && loadPending().some((r) => r.status === 'pending')) reconcile(render) }, 15000)

  render()
  return { box, render }
}
