// Security tab: signing history + the active ruleset version. Answers
// "what have I signed, and what protected me when I did?"
import { el, replace } from '../dom.js'
import { loadHistory, clearHistory } from '../insight/history.js'
import { activeRuleset, loadRuleset } from '../spam.js'
import { chainById } from '../config.js'

const OUTCOME = {
  approved: { cls: 'ok', label: 'approved' },
  rejected: { cls: 'dim', label: 'cancelled' },
  'blocked-then-cancelled': { cls: 'bad', label: 'blocked · cancelled' },
}

export function createSecurityView() {
  const box = el('div')

  function render() {
    const rows = loadHistory()
    const rs = activeRuleset()
    replace(box,
      el('h2', {}, 'Protection'),
      el('div', { class: 'approw good' },
        el('span', { style: 'flex:1' },
          `Spam ruleset v${rs.version} (${rs.updated || 'bundled'}) — ${rs.rules.length} rules, threshold ${rs.threshold}. `,
          el('span', { style: 'color:var(--dim)' }, 'Updates without a new release; the bundled copy is the fallback.'))),

      el('h2', {}, rows.length ? `Signing history — ${rows.length}` : 'Signing history'),
      rows.length
        ? el('div', {},
            el('div', { class: 'sig-note', style: 'margin-bottom:8px' },
              'Every request that reached the confirmation sheet, stored only on this device. Anything here you do not recognise is worth investigating.'),
            rows.slice(0, 60).map((r) => {
              const o = OUTCOME[r.outcome] || { cls: 'dim', label: r.outcome }
              return el('div', { class: 'actrow' },
                el('span', { class: 'when' }, new Date(r.at).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })),
                el('span', { class: 'what' },
                  el('b', {}, r.title || r.kind),
                  r.asset ? ` · ${r.asset}` : '',
                  r.chainId ? el('span', { style: 'color:var(--dim)' }, ` · ${chainById(r.chainId)?.name || r.chainId}`) : null,
                  r.findings?.length ? el('span', { style: 'color:var(--dim)' }, ` · ${r.findings.join(', ')}`) : null),
                el('span', { class: o.cls === 'ok' ? 'dir in' : o.cls === 'bad' ? 'dir out' : '', style: 'font-size:11px' }, o.label))
            }),
            el('div', { class: 'btnrow' },
              el('button', { class: 'ghost', onclick: () => { if (confirm('Clear the local signing history?')) { clearHistory(); render() } } }, 'Clear history')))
        : el('div', { class: 'empty' }, 'Nothing signed yet from this browser.'))
  }

  loadRuleset().then(render)
  render()
  return { box, render }
}
