// Phishing-domain checks backed by the vendored snapshot
// (public/blocklists/domains.json — MetaMask eth-phishing-detect + Phantom).
// Loaded lazily from our own origin; all checks are local.

let dataPromise = null
const load = () => (dataPromise ??= fetch(new URL('blocklists/domains.json', document.baseURI))
  .then((r) => r.json())
  .then((d) => ({ ...d, blockedSet: new Set(d.blocked) }))
  .catch(() => null))

const hostOf = (url) => {
  try { return new URL(String(url)).hostname.toLowerCase() } catch { return null }
}

// levenshtein with early exit — used for MetaMask-style fuzzy matching
function editDistance(a, b, max) {
  if (Math.abs(a.length - b.length) > max) return max + 1
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i)
  for (let i = 1; i <= a.length; i++) {
    const cur = [i]
    let rowMin = i
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1))
      rowMin = Math.min(rowMin, cur[j])
    }
    if (rowMin > max) return max + 1
    prev = cur
  }
  return prev[b.length]
}

// Returns { verdict: 'blocked'|'fuzzy'|'ok'|'unknown', reason? , host? }
export async function checkUrl(url) {
  const host = hostOf(url)
  if (!host) return { verdict: 'unknown' }
  const data = await load()
  if (!data) return { verdict: 'unknown', host }

  const parts = host.split('.')
  // exact + parent-domain match (a.b.evil.com matches evil.com)
  for (let i = 0; i < parts.length - 1; i++) {
    const candidate = parts.slice(i).join('.')
    if (data.whitelist.includes(candidate)) return { verdict: 'ok', host }
    if (data.blockedSet.has(candidate)) return { verdict: 'blocked', host, reason: `${candidate} is on the phishing blocklist` }
  }
  // fuzzy match against lookalike-prone names (metamask.io etc.)
  const stripped = host.replace(/\./g, '')
  for (const f of data.fuzzylist) {
    if (editDistance(stripped, f.replace(/\./g, ''), data.tolerance) <= data.tolerance) {
      return { verdict: 'fuzzy', host, reason: `${host} looks like a spoof of ${f}` }
    }
  }
  return { verdict: 'ok', host }
}

// Scan free text (NFT names/descriptions) for domain-shaped strings and check
// each — malicious NFTs love embedding phishing URLs in their names.
export async function checkTextForDomains(text) {
  const matches = String(text).match(/[a-z0-9][a-z0-9-]*(\.[a-z0-9][a-z0-9-]*)+/gi) || []
  for (const m of matches.slice(0, 10)) {
    const res = await checkUrl('https://' + m)
    if (res.verdict === 'blocked' || res.verdict === 'fuzzy') return res
  }
  return { verdict: 'ok' }
}
