import { keccak256 } from 'viem'
import { el, replace } from '../dom.js'
import { ZERO32, DEFAULT_PENDANT, chainById, HARDENED } from '../config.js'
import { deriveAddress, signTypedData } from '../vault.js'
import { buildTypedData, digests } from '../eip712.js'
import { saveProof, hiddenSet, saveHidden } from '../flex.js'
import { keyOf, refreshMetadata, fetchInstance } from '../indexer.js'
import { pendantPair, pendantAuthorize, renderPendantJpeg } from '../pendant.js'
import { canAnimate, extractFrames, captureFrames, concatFrames, toBase64 } from '../animation.js'
import { fallbackImg } from './gallery.js'
import { showQrModal } from './modal.js'
import { createSendBox } from './send.js'
import { decodeTypedData } from '../insight/decode.js'
import { evaluate } from '../insight/rules.js'
import { confirmSign } from '../insight/sheet.js'
import { safeLink } from './safelink.js'
import { client } from '../tx.js'
import { parseAbi } from 'viem'

const OWNER_ABI = parseAbi(['function ownerOf(uint256) view returns (address)'])

const PUSH_WINDOWS = [[300, '5 minutes (test expiry)'], [86400, '1 day'], [604800, '7 days'], [2592000, '30 days']]
const FLEX_WINDOWS = [[3600, '1 hour'], [28800, '8 hours'], [86400, '1 day'], [604800, '7 days'], [2592000, '30 days (cannot be revoked)']]

// Signing state lives OUTSIDE the rendered DOM. Re-rendering the detail pane
// (selecting a card, a background refresh) used to hand out a fresh enabled
// button and a fresh empty log while an operation was still awaiting the
// user's confirmation — so a second push could start and the first one's
// progress vanished. Keep both across renders.
let busy = false
let logLines = []      // { msg, cls } for the current selection
let logKey = null      // which NFT the lines belong to
let logEl = null

const log = (msg, cls = '') => {
  logLines.push({ msg, cls })
  if (!logEl) return
  logEl.append(el('div', { class: cls || null }, msg))
  logEl.scrollTop = 1e9
}

// Re-derive the owner account from the live device before any signature —
// catches device swaps between scan-time and sign-time. Then run the request
// through the insight engine and show the pre-sign sheet.
async function ownerGuardAndSign(n, message, heading) {
  log('checking connected device is the owner…')
  const liveAddr = await deriveAddress(n.ownerIndex)
  if (liveAddr.toLowerCase() !== n.owner.toLowerCase()) {
    throw new Error(`connected KeepKey is not this NFT's owner — device account ${n.ownerIndex} is ${liveAddr.slice(0, 10)}…, owner is ${n.owner.slice(0, 10)}…. Plug in the right device (or Rescan).`)
  }
  log('device matches owner ' + liveAddr.slice(0, 10) + '…', 'ok')

  const typedData = buildTypedData(n.chainId, message)
  const dg = digests(n.chainId, message)
  const action = decodeTypedData(typedData)
  const verdict = await evaluate({ action, chainId: n.chainId, ownerAddress: n.owner, nftName: n.name })

  const ok = await confirmSign({
    heading, action, verdict, digests: dg,
    meta: [{ k: 'signing account', v: `${n.owner.slice(0, 10)}… (#${n.ownerIndex})` }, { k: 'asset', v: n.name }],
    context: { account: n.owner, chainId: n.chainId, asset: n.name },
  })
  if (!ok) throw new Error('cancelled before signing')

  log('CONFIRM in Vault, then on your KeepKey…', 'act')
  const signature = await signTypedData(n.owner, typedData)
  log('signed ' + signature.slice(0, 18) + '…', 'ok')
  return signature
}

async function push(n, artImg, pendantUrl, windowSecs, refresh) {
  localStorage.setItem('pendant_url', pendantUrl)
  log('pairing with pendant…')
  const pair = await pendantPair(pendantUrl)
  log(`device ${String(pair.deviceId).slice(0, 14)}… nonce issued`, 'ok')

  // Animated source? Sample it into frames the pendant can hold. Falls back
  // to a still if the source turns out to be one frame or can't be decoded.
  let anim = null, bytes, b64
  const src = n.images?.[0]
  if (canAnimate() && src) {
    try {
      log('checking for animation…')
      let got = await extractFrames(src, {
        onProgress: (i, total) => log(`  frame ${i}/${total}`, ''),
      })
      if (got?.needsCapture) {
        log(`animated (${got.sourceFrames} frames) but the decoder won't take it — ` +
            `sampling the live image instead`, 'act')
        got = await captureFrames(artImg, {
          onProgress: (i, total) => log(`  captured ${i}/${total}`, ''),
        })
      }
      if (got) {
        const packed = concatFrames(got.frames)
        anim = {
          framesB64: got.frames.map(toBase64),
          delayMs: got.delayMs,
          bytes: packed,
        }
        log(`animated: ${got.sampled}${got.sourceFrames ? ' of ' + got.sourceFrames : ''} frames @ ${got.delayMs}ms ` +
            `(${(packed.length / 1024).toFixed(0)}KB)`, 'ok')
      }
    } catch (e) {
      log('animation extraction failed, falling back to still: ' + e.message, 'err')
    }
  }

  if (anim) {
    bytes = anim.bytes
  } else {
    log('rendering 466×466 JPEG…')
    ;({ bytes, b64 } = await renderPendantJpeg(artImg))
  }
  const imageHash = keccak256(bytes)
  log(`${anim ? 'frame pack' : 'image'} ${(bytes.length / 1024).toFixed(0)}KB, keccak ${imageHash.slice(0, 14)}…`, 'ok')

  const now = Math.floor(Date.now() / 1000)
  const message = {
    nftContract: n.contract, tokenId: n.tokenId, deviceId: pair.deviceId, nonce: pair.nonce,
    imageHash, issuedAt: String(now - 60), expiresAt: String(now + windowSecs),
  }
  const signature = await ownerGuardAndSign(n, message, 'Pendant display authorization')
  log('pushing to pendant (verifies sig + on-chain ownership)…')
  const out = await pendantAuthorize(pendantUrl, { chainId: n.chainId, ...message }, signature, b64, anim)
  log(`PENDANT AUTHORIZED — ${anim ? 'animating' : 'displaying'} ${n.name} as ${String(out.signer).slice(0, 10)}…`, 'ok')
  saveProof(n, message, signature)
  refresh()
}

async function flex(n, windowSecs, refresh) {
  const now = Math.floor(Date.now() / 1000)
  const nonce = keccak256(crypto.getRandomValues(new Uint8Array(32)))
  const message = {
    nftContract: n.contract, tokenId: n.tokenId,
    deviceId: ZERO32, nonce, imageHash: ZERO32,
    issuedAt: String(now - 60), expiresAt: String(now + windowSecs),
  }
  log(`broadcast flex for ${n.name}…`)
  const signature = await ownerGuardAndSign(n, message, 'Broadcast display proof')
  saveProof(n, message, signature)
  log('FLEX SIGNED — QR ready to share anywhere.', 'ok')
  refresh()
  showQrModal({ p: { chainId: n.chainId, ...message }, s: signature })
}

// A scan is a snapshot. Between scanning and acting the asset may have moved
// — sold on a marketplace, transferred from another client, or moved by us in
// another tab. Ask the chain before we let the user act on it, and say so
// plainly rather than letting them sign against a stale view.
// Case-insensitive address comparison, exported so the stale path is covered
// by tests rather than only by hoping the indexer is behind.
export const isStaleOwner = (onChainOwner, cachedOwner) =>
  !!onChainOwner && !!cachedOwner &&
  String(onChainOwner).toLowerCase() !== String(cachedOwner).toLowerCase()

async function verifyStillOwned(n, banner) {
  try {
    const owner = await client(n.chainId).readContract({
      address: n.contract, abi: OWNER_ABI, functionName: 'ownerOf', args: [BigInt(n.tokenId)],
    })
    if (isStaleOwner(owner, n.owner)) {
      replace(banner, el('div', { class: 'stale-warn' },
        `This is no longer in your wallet — ${owner.slice(0, 10)}… owns it now. Rescan to refresh.`))
      return false
    }
  } catch {
    // ERC-1155 has no ownerOf, and a dead RPC is not evidence of a sale;
    // stay silent rather than crying wolf.
  }
  return true
}

export function renderDetail(container, n, refresh, getAccounts) {
  if (!n) return replace(container, el('div', { class: 'empty' }, 'Select an NFT'))
  const chain = chainById(n.chainId)
  const artImg = fallbackImg(n.images, { class: 'art', crossorigin: 'anonymous' })

  const pendantUrl = el('input', { value: localStorage.getItem('pendant_url') || DEFAULT_PENDANT, 'aria-label': 'Pendant address' })
  const pushSel = el('select', {}, PUSH_WINDOWS.map(([v, t], i) => el('option', { value: v, selected: t === '7 days' || null }, t)))
  const flexSel = el('select', {}, FLEX_WINDOWS.map(([v, t]) => el('option', { value: v, selected: t === '1 hour' || null }, t)))

  const pushBtn = el('button', {}, 'Sign & Push')
  const flexBtn = el('button', {}, 'Sign Flex')

  // A signature is a one-at-a-time affair: the device can only confirm one
  // thing, and a second request would consume a nonce the first still needs.
  const guard = (btn, fn) => async () => {
    if (busy) { log('another signing operation is already in progress', 'err'); return }
    busy = true
    pushBtn.disabled = flexBtn.disabled = true
    try { await fn() } catch (e) { log('failed: ' + e.message, 'err') }
    busy = false
    pushBtn.disabled = !artReady()
    flexBtn.disabled = false
  }

  // Pushing needs decoded pixels; before the artwork loads the canvas is
  // empty and the push dies with a confusing "image not loaded".
  const artReady = () => !!artImg.naturalWidth
  const syncArt = () => {
    if (busy) return
    pushBtn.disabled = !artReady()
    pushBtn.textContent = artReady() ? 'Sign & Push' : 'Waiting for artwork…'
  }
  artImg.addEventListener('load', syncArt)
  artImg.addEventListener('error', syncArt)

  pushBtn.addEventListener('click', guard(pushBtn, () => push(n, artImg, pendantUrl.value, Number(pushSel.value), refresh)))
  flexBtn.addEventListener('click', guard(flexBtn, () => flex(n, Number(flexSel.value), refresh)))

  // restore the running operation's log instead of showing a blank pane
  const key = `${n.chainId}:${n.contract}:${n.tokenId}`
  if (key !== logKey && !busy) { logLines = []; logKey = key }
  const staleBanner = el('div')
  if (n.standard !== 'ERC-1155') verifyStillOwned(n, staleBanner)
  logEl = el('div', { id: 'log' }, logLines.map((l) => el('div', { class: l.cls || null }, l.msg)))

  // a render that lands mid-operation must not re-enable the buttons
  if (busy) {
    pushBtn.disabled = flexBtn.disabled = true
  } else {
    pushBtn.disabled = !artReady()
    pushBtn.textContent = artReady() ? 'Sign & Push' : 'Waiting for artwork…'
  }

  replace(container,
    staleBanner,
    artImg,
    el('div', { style: 'margin-top:14px' },
      el('div', { style: 'font-size:17px;font-weight:700' }, n.name),
      el('div', { class: 'row' }, el('span', {}, 'chain'), el('span', {}, `${n.chainName} (${n.chainId})`)),
      el('div', { class: 'row' }, el('span', {}, 'contract'), el('span', {}, n.contract)),
      el('div', { class: 'row' }, el('span', {}, 'token'), el('span', {}, '#' + n.tokenId)),
      n.standard === 'ERC-1155' && n.quantity
        ? el('div', { class: 'row' }, el('span', {}, 'you hold'), el('span', {}, `${n.quantity} copies`))
        : null,
      el('div', { class: 'row' }, el('span', {}, 'owner (your account)'), el('span', {}, `${n.owner.slice(0, 10)}… (account ${n.ownerIndex})`))),
    el('div', { class: 'links' },
      safeLink(`${chain.explorer}/nft/${n.contract}/${n.tokenId}`, `${chain.explorerName} ↗`),
      safeLink(`https://opensea.io/assets/${chain.opensea}/${n.contract}/${n.tokenId}`, 'OpenSea ↗'),
      safeLink(`https://zora.co/collect/${chain.zora}:${n.contract}/${n.tokenId}`, 'Zora ↗'),
      n.images[0] && safeLink(n.images[0], 'Raw image ↗'),
      el('a', {
        href: '#', style: 'cursor:pointer',
        onclick: async (e) => {
          e.preventDefault()
          const link = e.target
          link.textContent = 'refreshing…'
          await refreshMetadata(n)
          const fresh = await fetchInstance(n)
          if (fresh) {
            Object.assign(n, { name: fresh.name, images: fresh.images.length ? fresh.images : n.images, attributes: fresh.attributes })
            renderDetail(container, n, refresh, getAccounts)
          } else link.textContent = 'refresh failed'
        },
      }, '↻ refresh metadata')),
    el('div', { class: 'traits' }, (n.attributes || [])
      .filter((a) => a && (a.trait_type || a.value !== undefined))
      .map((a) => el('span', { class: 'trait' },
        el('b', {}, String(a.trait_type || 'trait').slice(0, 24)),
        String(a.value ?? '').slice(0, 32)))),
    el('div', { class: 'pushbox' },
      el('div', { class: 'boxtitle' }, 'Push to pendant'),
      el('label', {}, 'pendant address'), pendantUrl,
      el('label', {}, 'authorization window'), pushSel,
      el('div', { class: 'btnrow' }, pushBtn,
        el('button', { class: 'ghost', onclick: () => window.open(pendantUrl.value, '_blank', 'noopener') }, 'View pendant')),
      el('div', { class: 'divider' },
        el('div', { class: 'boxtitle' }, 'Broadcast flex ', el('span', { class: 'boxsub' }, '— shareable proof, no pendant needed')),
        el('label', {}, 'proof valid for'), flexSel,
        el('div', { class: 'btnrow' }, flexBtn)),
      createSendBox(n, log, refresh, getAccounts),
      logEl),
    el('button', {
      class: 'danger hidebtn',
      onclick: () => {
        if (!confirm(`Hide "${n.name}" from this gallery permanently?\n\n(It stays in your wallet on-chain — nothing can remove it from the blockchain — but this browser will never show it again unless you unhide it.)`)) return
        hiddenSet.add(keyOf(n)); saveHidden(); refresh(true)
      },
    }, 'Hide this NFT forever (this browser)'))
}
