// Seaport order decoding — the drainer's favourite instrument.
//
// A malicious "sign to claim" flow hands you a Seaport order that OFFERS your
// NFTs and asks for ~nothing in return. The signature looks like meaningless
// typed data; the consequence is your bag. This turns the order into the two
// facts that matter: what leaves, and what comes back.
import { formatEther, getAddress } from 'viem'

const ITEM_TYPE = ['native token', 'ERC-20', 'ERC-721', 'ERC-1155', 'ERC-721 (criteria)', 'ERC-1155 (criteria)']
const ZERO = '0x0000000000000000000000000000000000000000'

const num = (v) => { try { return BigInt(v ?? 0) } catch { return 0n } }

function describeItem(it, { isOffer }) {
  const type = ITEM_TYPE[Number(it.itemType ?? 0)] || 'unknown'
  const token = it.token && it.token !== ZERO ? getAddress(it.token) : null
  const amount = num(it.startAmount ?? it.amount)
  if (Number(it.itemType) === 0 || (!token && amount)) {
    return { kind: 'native', text: `${formatEther(amount)} ETH`, amount }
  }
  if (Number(it.itemType) === 1) {
    return { kind: 'erc20', text: `${amount} units of token ${token?.slice(0, 10)}…`, token, amount }
  }
  const id = it.identifierOrCriteria !== undefined ? String(it.identifierOrCriteria) : '?'
  const criteria = Number(it.itemType) >= 4
  return {
    kind: 'nft',
    text: criteria
      ? `ANY token from collection ${token?.slice(0, 10)}… (criteria order)`
      : `${type} #${id} from ${token?.slice(0, 10)}…`,
    token, tokenId: id, criteria,
  }
}

// Returns null when this isn't a Seaport-shaped message.
export function decodeSeaportOrder(typedData) {
  const m = typedData?.message
  if (!m || !Array.isArray(m.offer) || !Array.isArray(m.consideration)) return null

  const offered = m.offer.map((i) => describeItem(i, { isOffer: true }))
  const received = m.consideration.map((i) => describeItem(i, { isOffer: false }))
  const offerer = m.offerer ? getAddress(m.offerer) : null

  // Total value coming back to the offerer, as far as we can tell locally.
  const incomingNative = received
    .filter((r) => r.kind === 'native')
    .reduce((s, r) => s + (r.amount || 0n), 0n)
  const givingNfts = offered.filter((o) => o.kind === 'nft')
  const anyCriteria = givingNfts.some((o) => o.criteria)

  const endTime = m.endTime ? Number(m.endTime) : null
  const durationDays = endTime ? (endTime - Date.now() / 1000) / 86400 : null

  return {
    offerer,
    offered, received,
    givingNftCount: givingNfts.length,
    incomingNative,
    anyCriteria,
    endTime,
    durationDays,
    // The shape that ruins people: you give NFTs, you get ~nothing back.
    isGiveaway: givingNfts.length > 0 && incomingNative === 0n &&
      !received.some((r) => r.kind === 'erc20' && (r.amount || 0n) > 0n),
    zone: m.zone && m.zone !== ZERO ? getAddress(m.zone) : null,
  }
}

export function seaportAction(order, typedData) {
  const fields = [
    ...order.offered.map((o, i) => ({ k: `you give #${i + 1}`, v: o.text })),
    ...order.received.map((r, i) => ({ k: `you receive #${i + 1}`, v: r.text })),
    order.offerer ? { k: 'offerer', v: order.offerer } : null,
    order.endTime ? { k: 'valid until', v: new Date(order.endTime * 1000).toLocaleString() } : null,
  ].filter(Boolean)

  const plain = order.isGiveaway
    ? `This order GIVES AWAY ${order.givingNftCount} item(s) and returns nothing. Signing it lets anyone take them for free.`
    : `You are offering ${order.givingNftCount || order.offered.length} item(s) in exchange for ${order.received.map((r) => r.text).join(', ') || 'nothing'}.`

  return {
    kind: 'marketplace-order',
    known: true,
    title: order.isGiveaway ? 'Order that gives your NFTs away' : 'Marketplace order (Seaport)',
    plain,
    spendsAssets: true,
    fields,
    order,
  }
}
