// Decoders: turn raw calldata / typed data into structured "actions" a human
// can read. Modeled on Rabby's rabby-action layer (MIT) — same idea, our own
// minimal implementation covering what this wallet actually signs plus the
// hostile things a malicious dapp might slip in.
import { decodeFunctionData, parseAbi, formatUnits, getAddress } from 'viem'
import { ZERO32 } from '../config.js'
import { decodeSeaportOrder, seaportAction } from './seaport.js'

export const ABIS = parseAbi([
  'function safeTransferFrom(address from, address to, uint256 tokenId)',
  'function safeTransferFrom(address from, address to, uint256 id, uint256 amount, bytes data)',
  'function transferFrom(address from, address to, uint256 tokenId)',
  'function approve(address to, uint256 tokenIdOrAmount)',
  'function setApprovalForAll(address operator, bool approved)',
  'function transfer(address to, uint256 amount)',
  'function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s)',
])

const short = (a) => `${String(a).slice(0, 6)}…${String(a).slice(-4)}`

// ---- calldata → action ----------------------------------------------------
export function decodeCalldata(data, { to } = {}) {
  if (!data || data === '0x') return { kind: 'native-only', title: 'Plain value transfer', fields: [] }
  let d
  try { d = decodeFunctionData({ abi: ABIS, data }) } catch {
    return { kind: 'unknown', title: 'Unrecognized contract call',
      fields: [{ k: 'selector', v: String(data).slice(0, 10) }, { k: 'contract', v: to || '?' }], unknown: true }
  }
  const a = d.args
  switch (d.functionName) {
    case 'safeTransferFrom':
    case 'transferFrom':
      return {
        kind: 'nft-transfer',
        title: a.length > 3 ? 'Transfer NFT (ERC-1155)' : 'Transfer NFT (ERC-721)',
        from: a[0], to: a[1], tokenId: a[2],
        amount: a.length > 3 ? a[3] : 1n,
        fields: [
          { k: 'from', v: getAddress(a[0]) },
          { k: 'to', v: getAddress(a[1]) },
          { k: 'token id', v: String(a[2]) },
          ...(a.length > 3 ? [{ k: 'amount', v: String(a[3]) }] : []),
        ],
      }
    case 'setApprovalForAll':
      return {
        kind: 'approve-all', title: a[1] ? 'Approve ALL NFTs in this collection' : 'Revoke collection approval',
        operator: a[0], approved: a[1],
        fields: [{ k: 'operator', v: getAddress(a[0]) }, { k: 'approved', v: String(a[1]) }],
      }
    case 'approve':
      return {
        kind: 'approve', title: 'Approve token/NFT to a spender',
        spender: a[0], value: a[1],
        fields: [{ k: 'spender', v: getAddress(a[0]) }, { k: 'token id / amount', v: String(a[1]) }],
      }
    case 'transfer':
      return { kind: 'token-transfer', title: 'Transfer tokens', to: a[0], value: a[1],
        fields: [{ k: 'to', v: getAddress(a[0]) }, { k: 'amount (raw)', v: String(a[1]) }] }
    case 'permit':
      return { kind: 'permit', title: 'Gasless spending permit', spender: a[1], value: a[2], deadline: a[3],
        fields: [{ k: 'spender', v: getAddress(a[1]) }, { k: 'amount (raw)', v: String(a[2]) },
          { k: 'deadline', v: new Date(Number(a[3]) * 1000).toLocaleString() }] }
    default:
      return { kind: 'unknown', title: `Call: ${d.functionName}`, fields: [], unknown: true }
  }
}

// ---- typed data → action --------------------------------------------------
// Known pattern: our own DisplayAuthorization renders in plain English.
export function decodeTypedData(typedData) {
  const primary = typedData?.primaryType
  const m = typedData?.message || {}
  if (primary === 'DisplayAuthorization') {
    const broadcast = m.deviceId === ZERO32
    const until = new Date(Number(m.expiresAt) * 1000)
    return {
      kind: 'display-authorization', known: true,
      title: broadcast ? 'Authorize public display of your NFT' : 'Authorize display on one pendant',
      plain: broadcast
        ? `Anyone holding this proof may display token #${m.tokenId} as yours until ${until.toLocaleString()}. This does not move or spend anything.`
        : `Only the paired pendant (${short(m.deviceId)}) may display token #${m.tokenId} until ${until.toLocaleString()}. This does not move or spend anything.`,
      spendsAssets: false,
      fields: [
        { k: 'collection', v: getAddress(m.nftContract) },
        { k: 'token id', v: String(m.tokenId) },
        { k: 'display', v: broadcast ? 'any surface (broadcast)' : `device ${short(m.deviceId)}` },
        { k: 'image binding', v: m.imageHash === ZERO32 ? 'canonical artwork' : short(m.imageHash) },
        { k: 'expires', v: until.toLocaleString() },
      ],
      expiresAt: Number(m.expiresAt),
    }
  }
  // Seaport-family orders are the classic drainer vector — decode what the
  // order actually moves rather than warning generically.
  if (primary === 'OrderComponents' || primary === 'OrderParameters' || /seaport/i.test(typedData?.domain?.name || '')) {
    const order = decodeSeaportOrder(typedData)
    if (order) return seaportAction(order, typedData)
    return {
      kind: 'marketplace-order', known: false, title: 'Marketplace order (Seaport)',
      plain: 'This signature can SELL or TRANSFER your NFTs if someone fulfills it. Only sign on a marketplace you trust, at a price you chose.',
      spendsAssets: true,
      fields: [{ k: 'domain', v: String(typedData?.domain?.name || '?') }, { k: 'type', v: primary }],
    }
  }
  if (primary === 'Permit' || primary === 'PermitSingle' || primary === 'PermitBatch') {
    return {
      kind: 'permit-signature', known: false, title: 'Token spending permit',
      plain: 'This signature lets a spender move your tokens without another transaction.',
      spendsAssets: true,
      fields: Object.entries(m).slice(0, 6).map(([k, v]) => ({ k, v: String(v).slice(0, 60) })),
    }
  }
  return {
    kind: 'typed-unknown', known: false, title: `Typed data: ${primary || 'unknown'}`,
    plain: 'This wallet cannot decode this message. Only sign it if you understand what the requesting app does with it.',
    spendsAssets: true,
    fields: Object.entries(m).slice(0, 8).map(([k, v]) => ({ k, v: String(v).slice(0, 60) })),
  }
}
