// NFT transfer transactions: build calldata, estimate, hardware-sign via
// Vault, broadcast via public RPC, await receipt. The device screen is the
// final authority on what gets signed — this module's job is to construct
// honestly and show everything before asking.
import { createPublicClient, http, fallback, encodeFunctionData, parseAbi, isAddress, getAddress, formatEther } from 'viem'
import { mainnet, base, optimism, arbitrum, polygon, zora } from 'viem/chains'
import { normalize } from 'viem/ens'
import { chainById, HARDENED } from './config.js'
import { signTransaction } from './vault.js'

const VIEM_CHAINS = { 1: mainnet, 8453: base, 10: optimism, 42161: arbitrum, 137: polygon, 7777777: zora }
const clients = {}
export function client(chainId) {
  if (!clients[chainId]) {
    const cfg = chainById(chainId)
    clients[chainId] = createPublicClient({ chain: VIEM_CHAINS[chainId], transport: fallback(cfg.rpcs.map((u) => http(u))) })
  }
  return clients[chainId]
}

const ERC721_ABI = parseAbi(['function safeTransferFrom(address from, address to, uint256 tokenId)'])
const ERC1155_ABI = parseAbi(['function safeTransferFrom(address from, address to, uint256 id, uint256 amount, bytes data)'])

// Accepts 0x address or ENS name (resolved via mainnet ENS regardless of the
// NFT's chain — standard wallet behavior). Returns checksummed address.
export async function resolveRecipient(input) {
  const s = input.trim()
  if (isAddress(s)) return getAddress(s)
  if (/^[a-z0-9-]+(\.[a-z0-9-]+)*\.eth$/i.test(s)) {
    const addr = await client(1).getEnsAddress({ name: normalize(s) })
    if (!addr) throw new Error(`ENS name ${s} does not resolve`)
    return getAddress(addr)
  }
  throw new Error('recipient must be a 0x address or an ENS name')
}

// ERC-1155 balances are fungible within a token id: holding 5 copies and
// sending 2 is normal. Sending a hardcoded 1 silently did the wrong thing for
// anyone holding multiples.
export async function prepareTransfer(n, to, amount = 1n) {
  const c = client(n.chainId)
  const from = getAddress(n.owner)
  const is1155 = n.standard === 'ERC-1155'
  const qty = is1155 ? BigInt(amount) : 1n
  if (is1155) {
    if (qty < 1n) throw new Error('amount must be at least 1')
    const held = n.quantity ? BigInt(n.quantity) : null
    if (held !== null && qty > held) throw new Error(`you hold ${held}, cannot send ${qty}`)
  }
  const data = is1155
    ? encodeFunctionData({ abi: ERC1155_ABI, functionName: 'safeTransferFrom', args: [from, to, BigInt(n.tokenId), qty, '0x'] })
    : encodeFunctionData({ abi: ERC721_ABI, functionName: 'safeTransferFrom', args: [from, to, BigInt(n.tokenId)] })
  const [gas, fees, nonce] = await Promise.all([
    c.estimateGas({ account: from, to: n.contract, data }),
    c.estimateFeesPerGas(),
    c.getTransactionCount({ address: from, blockTag: 'pending' }),
  ])
  const gasLimit = (gas * 12n) / 10n
  const feeWei = gasLimit * fees.maxFeePerGas
  return {
    tx: {
      to: n.contract, data, nonce, gasLimit,
      maxFeePerGas: fees.maxFeePerGas, maxPriorityFeePerGas: fees.maxPriorityFeePerGas,
      chainId: n.chainId,
    },
    feeEstimate: formatEther(feeWei),
    amount: qty,
  }
}

const hex = (v) => '0x' + BigInt(v).toString(16)

// Vault's /eth/sign-transaction returns { r, s, v, serialized } — verified
// against a real KeepKey signature on 2026-08-02 (mainnet tx
// 0xfe83324530cb7ea23a876766e8bb8a292abe38cc0aa0678de33e528d2b8dfa21).
// The alternates are kept as a courtesy to older/other Vault builds, but
// `serialized` is the shape that actually ships. Shared with the approvals
// revoke path so both writes parse identically.
export function extractSignedTx(out) {
  const raw = out?.serialized || out?.raw || out?.signedTx || out?.rawTransaction ||
              (typeof out === 'string' ? out : null)
  if (!raw || typeof raw !== 'string' || !/^0x[0-9a-fA-F]+$/.test(raw)) return null
  return raw
}

export async function signAndBroadcast(n, prep) {
  const out = await signTransaction({
    addressNList: [HARDENED + 44, HARDENED + 60, HARDENED + n.ownerIndex, 0, 0],
    nonce: hex(prep.tx.nonce), gasLimit: hex(prep.tx.gasLimit),
    maxFeePerGas: hex(prep.tx.maxFeePerGas), maxPriorityFeePerGas: hex(prep.tx.maxPriorityFeePerGas),
    value: '0x0', to: prep.tx.to, chainId: prep.tx.chainId, data: prep.tx.data,
  })
  const raw = extractSignedTx(out)
  if (!raw) throw new Error('unexpected sign-transaction response: ' + JSON.stringify(out).slice(0, 200))
  const hash = await client(n.chainId).sendRawTransaction({ serializedTransaction: raw })
  return hash
}

export const waitForReceipt = (chainId, hash) =>
  client(chainId).waitForTransactionReceipt({ hash, timeout: 180_000 })

// ---- replacement transactions (speed up / cancel) -------------------------
// Ethereum has no "cancel" — you replace a pending transaction by sending a
// different one with the SAME nonce and a high enough fee that miners prefer
// it. Speed-up re-sends the same call; cancel sends an empty self-transfer.
// Nodes generally require ~10% higher fees to accept a replacement, so bump
// by 25% to leave room for a rising base fee.
const BUMP_NUM = 125n, BUMP_DEN = 100n

export async function prepareReplacement(pending, mode) {
  const c = client(pending.chainId)
  const tx = await c.getTransaction({ hash: pending.hash }).catch(() => null)
  if (!tx) throw new Error('transaction is no longer in the mempool — it may have already confirmed')

  const fees = await c.estimateFeesPerGas()
  const bump = (a, b) => { const x = (a * BUMP_NUM) / BUMP_DEN; return x > b ? x : b }
  const maxFeePerGas = bump(tx.maxFeePerGas ?? tx.gasPrice ?? 0n, fees.maxFeePerGas)
  const maxPriorityFeePerGas = bump(tx.maxPriorityFeePerGas ?? 0n, fees.maxPriorityFeePerGas)

  const cancelling = mode === 'cancel'
  return {
    tx: {
      to: cancelling ? getAddress(pending.from) : tx.to,
      data: cancelling ? '0x' : tx.input,
      value: 0n,
      nonce: Number(tx.nonce),
      gasLimit: cancelling ? 21000n : tx.gas,
      maxFeePerGas, maxPriorityFeePerGas,
      chainId: pending.chainId,
    },
    feeEstimate: formatEther((cancelling ? 21000n : tx.gas) * maxFeePerGas),
    mode,
  }
}

// Sign + broadcast an arbitrary prepared tx (used by replacements). Returns
// the new hash, which replaces the old one at the same nonce.
export async function signAndSend(accountIndex, prep) {
  const out = await signTransaction({
    addressNList: [HARDENED + 44, HARDENED + 60, HARDENED + accountIndex, 0, 0],
    nonce: hex(prep.tx.nonce), gasLimit: hex(prep.tx.gasLimit),
    maxFeePerGas: hex(prep.tx.maxFeePerGas), maxPriorityFeePerGas: hex(prep.tx.maxPriorityFeePerGas),
    value: hex(prep.tx.value ?? 0n), to: prep.tx.to, chainId: prep.tx.chainId,
    data: prep.tx.data ?? '0x',
  })
  const raw = extractSignedTx(out)
  if (!raw) throw new Error('unexpected sign-transaction response: ' + JSON.stringify(out).slice(0, 200))
  return client(prep.tx.chainId).sendRawTransaction({ serializedTransaction: raw })
}
