// Animated NFT support.
//
// The pendant can't decode a 17MB GIF, and 165 frames of 466x466 would be
// 71MB of pixels against 8MB of PSRAM. So the browser does the work: decode
// the source with WebCodecs, sample a handful of frames evenly across the
// loop, crop each to 466x466, and ship them as small JPEGs. The device
// decodes them once into PSRAM and loops them as DMA blits.
//
// No server, no ffmpeg — ImageDecoder ships in the browser.
import { PENDANT_PX } from './config.js'

export const MAX_FRAMES = 12          // must match KK_MAX_FRAMES in firmware
const JPEG_QUALITY = 0.82

export const canAnimate = () => typeof ImageDecoder !== 'undefined'

// Does this byte stream contain more than one frame? GIF marks each frame
// with a Graphic Control Extension (0x21 0xF9 0x04); APNG uses fcTL chunks.
// Cheap, and it doesn't depend on a decoder that may refuse the file.
export function countFrames(bytes) {
  const b = new Uint8Array(bytes)
  const isGif = b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46
  const needle = isGif ? [0x21, 0xf9, 0x04] : [0x66, 0x63, 0x54, 0x4c]  // GCE | fcTL
  let n = 0
  for (let i = 0; i < b.length - needle.length; i++) {
    let hit = true
    for (let k = 0; k < needle.length; k++) if (b[i + k] !== needle[k]) { hit = false; break }
    if (hit) n++
  }
  return n
}

// Fallback capture: the browser is ALREADY playing the animation in an <img>.
// Sampling that element onto a canvas grabs whatever frame is on screen, which
// works for sources WebCodecs won't decode (this 17MB GIF reports zero tracks).
// Less precise than frame-indexed decoding — we get whatever the playhead is
// on — but for a loop that reads identically.
// sampleMs must exceed the source's frame duration or we capture duplicates;
// playbackMs is how fast the pendant loops what we captured (faster than we
// sampled = a condensed, livelier loop).
export async function captureFrames(imgEl, { maxFrames = MAX_FRAMES, sampleMs = 300, playbackMs = 140, onProgress } = {}) {
  if (!imgEl?.naturalWidth) throw new Error('artwork not loaded')
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = PENDANT_PX
  const ctx = canvas.getContext('2d')
  const side = Math.min(imgEl.naturalWidth, imgEl.naturalHeight)
  const sx = (imgEl.naturalWidth - side) / 2
  const sy = (imgEl.naturalHeight - side) / 2

  const frames = []
  for (let i = 0; i < maxFrames; i++) {
    ctx.drawImage(imgEl, sx, sy, side, side, 0, 0, PENDANT_PX, PENDANT_PX)
    const blob = await new Promise((r) => canvas.toBlob(r, 'image/jpeg', JPEG_QUALITY))
    frames.push(new Uint8Array(await blob.arrayBuffer()))
    onProgress?.(i + 1, maxFrames)
    if (i < maxFrames - 1) await new Promise((r) => setTimeout(r, sampleMs))
  }
  return { frames, delayMs: playbackMs, sourceFrames: null, sampled: frames.length, viaCapture: true }
}

// Is this URL likely animated? (cheap check before fetching megabytes)
export const looksAnimated = (url) => /\.(gif|webp|apng)(\?|$)/i.test(String(url || ''))

// Decode → sample → crop → JPEG. Returns null if the source is a still.
export async function extractFrames(url, { maxFrames = MAX_FRAMES, onProgress } = {}) {
  if (!canAnimate()) return null
  const res = await fetch(url)
  if (!res.ok) throw new Error(`fetch failed (${res.status})`)
  const type = res.headers.get('content-type') || ''
  const buf = await res.arrayBuffer()

  const mime = /image\/(gif|webp|png|avif)/.test(type) ? type.split(';')[0] : 'image/gif'
  if (!(await ImageDecoder.isTypeSupported(mime))) return null

  const embedded = countFrames(buf)
  let decoder = null, track = null, total = 1
  try {
    decoder = new ImageDecoder({ data: buf, type: mime })
    await decoder.completed
    track = decoder.tracks.selectedTrack
    total = track?.frameCount ?? 1
  } catch { /* fall through to capture */ }

  // WebCodecs refuses some files (large GIFs come back with zero tracks) even
  // though they are clearly animated. Say so, and let the caller sample the
  // element the browser is already happily playing.
  if (!decoder || !decoder.tracks.length || total <= 1) {
    decoder?.close?.()
    return embedded > 1 ? { needsCapture: true, sourceFrames: embedded } : null
  }

  // Even sampling across the loop keeps the motion readable; taking the
  // first N would just show the opening beat.
  const step = total / Math.min(maxFrames, total)
  const picks = Array.from({ length: Math.min(maxFrames, total) }, (_, i) => Math.floor(i * step))

  const canvas = new OffscreenCanvas(PENDANT_PX, PENDANT_PX)
  const ctx = canvas.getContext('2d')
  const frames = []
  let totalDurationUs = 0

  for (const [n, idx] of picks.entries()) {
    const { image } = await decoder.decode({ frameIndex: idx })
    totalDurationUs += image.duration ?? 0
    const side = Math.min(image.displayWidth, image.displayHeight)
    ctx.drawImage(image,
      (image.displayWidth - side) / 2, (image.displayHeight - side) / 2, side, side,
      0, 0, PENDANT_PX, PENDANT_PX)
    image.close?.()
    const blob = await canvas.convertToBlob({ type: 'image/jpeg', quality: JPEG_QUALITY })
    frames.push(new Uint8Array(await blob.arrayBuffer()))
    onProgress?.(n + 1, picks.length)
  }
  decoder.close?.()

  // Play the sampled frames over the source loop's real duration, so a 2s
  // animation still reads as 2s rather than racing.
  const srcLoopMs = totalDurationUs ? (totalDurationUs / 1000) * (total / picks.length) : picks.length * 100
  const delayMs = Math.max(40, Math.round(srcLoopMs / picks.length))

  return { frames, delayMs, sourceFrames: total, sampled: picks.length }
}

// Frame pack hashing: concatenation in order, so the signature commits to
// every frame AND their sequence.
export function concatFrames(frames) {
  const total = frames.reduce((n, f) => n + f.length, 0)
  const out = new Uint8Array(total)
  let o = 0
  for (const f of frames) { out.set(f, o); o += f.length }
  return out
}

export const toBase64 = (bytes) => {
  let bin = ''
  for (let i = 0; i < bytes.length; i += 0x8000) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000))
  }
  return btoa(bin)
}
