// Approvals manager: what you've granted, and one-click hardware-signed
// revocation. Standing approvals are the #1 NFT-theft vector, so this view is
// deliberately blunt about risk.
import { el, replace } from '../dom.js'
import { encodeFunctionData, formatUnits } from 'viem'
import { findApprovals, revokeCalldata } from '../approvals.js'
import { chainById, HARDENED } from '../config.js'
import { client, extractSignedTx } from '../tx.js'
import { signTransaction } from '../vault.js'
import { decodeCalldata } from '../insight/decode.js'
import { evaluate } from '../insight/rules.js'
import { confirmSign } from '../insight/sheet.js'
import { simulateRevoke } from '../insight/simulate.js'
import { labelFor } from '../labels.js'

const short = (a) => `${String(a).slice(0, 8)}…${String(a).slice(-6)}`

export function createApprovalsView(getAccounts) {
  const box = el('div')
  let state = { loading: false, scanned: false, items: [] }

  async function scan() {
    const accounts = getAccounts()
    if (!accounts.length) return
    state = { ...state, loading: true }
    render()
    try {
      state.items = await findApprovals(accounts)
      state.scanned = true
    } finally {
      state.loading = false
      render()
    }
  }

  async function revoke(ap) {
    const chain = chainById(ap.chainId)
    const cl = client(ap.chainId)
    const { abi, functionName, args } = revokeCalldata(ap)
    const data = encodeFunctionData({ abi, functionName, args })
    const [gas, fees, nonce] = await Promise.all([
      cl.estimateGas({ account: ap.owner, to: ap.contract, data }),
      cl.estimateFeesPerGas(),
      cl.getTransactionCount({ address: ap.owner, blockTag: 'pending' }),
    ])
    const gasLimit = (gas * 12n) / 10n
    const sim = await simulateRevoke({ chainId: ap.chainId, owner: ap.owner, operator: ap.operator, contract: ap.contract, data })
    const action = decodeCalldata(data, { to: ap.contract })
    const verdict = await evaluate({ action, chainId: ap.chainId, ownerAddress: ap.owner, simulation: sim })
    verdict.findings.unshift({ level: 'safe', code: 'revocation', text: 'This REMOVES a permission. It cannot move or spend anything.' })
    verdict.blocked = false

    const ok = await confirmSign({
      heading: `Revoke approval on ${chain.name}`,
      action: { ...action, title: 'Revoke approval', plain: `Removes ${short(ap.operator)}'s permission over ${ap.contractName || short(ap.contract)}.` },
      verdict,
      balanceChanges: sim.changes.map((c) => ({ direction: 'in', what: c.what, detail: `${c.before} → ${c.after}` })),
      context: { account: ap.owner, chainId: ap.chainId, asset: ap.contractName || ap.contract },
      meta: [{ k: 'collection/token', v: ap.contract }, { k: 'operator', v: ap.operator }, { k: 'account', v: ap.owner }],
    })
    if (!ok) return

    const hex = (v) => '0x' + BigInt(v).toString(16)
    const out = await signTransaction({
      addressNList: [HARDENED + 44, HARDENED + 60, HARDENED + ap.ownerIndex, 0, 0],
      nonce: hex(nonce), gasLimit: hex(gasLimit),
      maxFeePerGas: hex(fees.maxFeePerGas), maxPriorityFeePerGas: hex(fees.maxPriorityFeePerGas),
      value: '0x0', to: ap.contract, chainId: ap.chainId, data,
    })
    const raw = extractSignedTx(out)
    if (!raw) throw new Error('unexpected sign response: ' + JSON.stringify(out).slice(0, 200))
    const hash = await cl.sendRawTransaction({ serializedTransaction: raw })
    alert(`Revocation broadcast:\n${hash}\n\nTrack it at ${chain.explorer}/tx/${hash}`)
    await cl.waitForTransactionReceipt({ hash, timeout: 180_000 })
    scan()
  }

  function render() {
    if (state.loading) return replace(box, el('h2', {}, 'Approvals'), el('div', { class: 'empty' }, 'Scanning approval history and confirming on-chain state…'))
    if (!state.scanned) {
      return replace(box,
        el('h2', {}, 'Approvals'),
        el('div', { class: 'approw' },
          el('span', { style: 'flex:1' }, 'Standing approvals let contracts move your assets without asking again — the top NFT-theft vector.'),
          el('button', { class: 'ghost', onclick: scan }, 'Scan approvals')))
    }
    if (!state.items.length) {
      return replace(box, el('h2', {}, 'Approvals'),
        el('div', { class: 'approw good' }, el('span', { style: 'flex:1' }, '✓ No active approvals found on the scanned accounts.'),
          el('button', { class: 'ghost', onclick: scan }, 'Rescan')))
    }
    replace(box,
      el('h2', {}, `Approvals — ${state.items.length} active`),
      el('div', { class: 'prooflist' }, state.items.map((ap) =>
        el('div', { class: ap.kind === 'collection' || ap.unlimited ? 'approw danger' : 'approw' },
          el('div', { style: 'flex:1;min-width:0' },
            el('div', {}, el('b', {}, ap.contractName || short(ap.contract)),
              ap.kind === 'collection'
                ? ' · ALL NFTs in this collection'
                : ap.unlimited
                  ? ' · UNLIMITED spending allowance'
                  : ` · allowance ${Intl.NumberFormat(undefined, { maximumFractionDigits: 4, notation: 'compact' }).format(Number(formatUnits(ap.amount, ap.decimals ?? 18)))} tokens`),
            el('div', { class: 'apsub' },
              `operator ${labelFor(ap.operator)?.text || short(ap.operator)} · ${ap.chainName} · account #${ap.ownerIndex}`)),
          el('button', { class: 'danger', onclick: async (e) => { e.target.disabled = true; try { await revoke(ap) } catch (err) { alert('revoke failed: ' + err.message) } e.target.disabled = false } }, 'Revoke'))),
        el('div', { class: 'sig-note' }, 'Revoking costs gas but permanently removes the permission.')))
  }

  render()
  return { box, scan }
}
