// Durable record of in-flight transactions.
//
// Broadcasting is the point of no return: the transaction exists on the
// network whether or not this tab survives. Keeping the record only in page
// memory meant a reload, a crash, or a closed laptop lost the user's only
// handle on it — they'd be left guessing whether an NFT moved. This persists
// each broadcast immediately and reconciles against the chain on load.
import { client } from './tx.js'

const KEY = 'kk_pending_tx'
const MAX = 30

const load = () => { try { return JSON.parse(localStorage.getItem(KEY) || '[]') } catch { return [] } }
const save = (rows) => localStorage.setItem(KEY, JSON.stringify(rows.slice(0, MAX)))

export const loadPending = load

// Called the instant a hash comes back, before waiting for the receipt.
export function recordBroadcast({ hash, chainId, chainName, kind, asset, from, to, nonce, account, accountIndex }) {
  const rows = load()
  rows.unshift({
    hash, chainId, chainName, kind, asset, from, to,
    nonce: nonce !== undefined ? String(nonce) : null,
    account, accountIndex,
    status: 'pending', at: Date.now(),
  })
  save(rows)
  return hash
}

export function settle(hash, status, blockNumber) {
  const rows = load()
  const row = rows.find((r) => r.hash === hash)
  if (row) {
    row.status = status                     // 'success' | 'reverted' | 'dropped'
    row.blockNumber = blockNumber ? String(blockNumber) : null
    row.settledAt = Date.now()
    save(rows)
  }
}

export function forget(hash) {
  save(load().filter((r) => r.hash !== hash))
}

// On load, ask the chain what happened to anything still marked pending.
// A transaction can also be legitimately gone (dropped from mempool, or
// replaced by a speed-up), which is why "not found" is its own outcome
// rather than an error.
export async function reconcile(onUpdate) {
  const rows = load().filter((r) => r.status === 'pending')
  for (const r of rows) {
    try {
      const receipt = await client(r.chainId).getTransactionReceipt({ hash: r.hash })
      settle(r.hash, receipt.status === 'success' ? 'success' : 'reverted', receipt.blockNumber)
    } catch {
      // no receipt yet: still pending, unless it has aged out of plausibility
      const ageMin = (Date.now() - r.at) / 60000
      if (ageMin > 60) settle(r.hash, 'dropped', null)
    }
    onUpdate?.()
  }
}

// prune settled rows after a day so the list stays a live view, not a ledger
export function prune() {
  const cutoff = Date.now() - 86400_000
  save(load().filter((r) => r.status === 'pending' || (r.settledAt ?? r.at) > cutoff))
}
