// Hardware-signed NFT transfer, gated by the insight engine's pre-sign sheet.
// Also the emergency proof revoke (self-transfer).
import { el } from '../dom.js'
import { chainById } from '../config.js'
import { loadProofs } from '../flex.js'
import { resolveRecipient, prepareTransfer, signAndBroadcast, waitForReceipt, client } from '../tx.js'
import { decodeCalldata } from '../insight/decode.js'
import { evaluate } from '../insight/rules.js'
import { confirmSign } from '../insight/sheet.js'
import { simulateTransfer } from '../insight/simulate.js'
import { recordBroadcast, settle } from '../pending.js'

export function createSendBox(n, log, refresh, getAccounts) {
  const chain = chainById(n.chainId)
  const input = el('input', { placeholder: '0x address or ENS name' })
  const held = n.standard === 'ERC-1155' && n.quantity ? BigInt(n.quantity) : null
  const amountInput = held !== null
    ? el('input', { type: 'number', min: '1', max: String(held), value: '1', 'aria-label': `Amount to send (you hold ${held})` })
    : null
  const sendBtn = el('button', {}, 'Send NFT')

  sendBtn.addEventListener('click', async () => {
    sendBtn.disabled = true
    try {
      log('resolving recipient…')
      const to = await resolveRecipient(input.value)
      log(`recipient ${to}`, 'ok')

      log('estimating gas + fetching nonce…')
      const amount = amountInput ? BigInt(amountInput.value || '1') : 1n
      const prep = await prepareTransfer(n, to, amount)
      log(`network fee ≈ ${Number(prep.feeEstimate).toFixed(6)} ETH on ${chain.name}`, 'ok')

      // context for the rules: is the recipient a contract? seen before? proofs at stake?
      let recipientCode = '0x'
      try { recipientCode = await client(n.chainId).getBytecode({ address: to }) || '0x' } catch {}
      const now = Math.floor(Date.now() / 1000)
      const activeProofs = loadProofs().filter((f) => f.expiresAt > now &&
        f.bundle.p.nftContract.toLowerCase() === n.contract.toLowerCase() && String(f.bundle.p.tokenId) === n.tokenId).length

      log('simulating against current chain state…')
      const sim = await simulateTransfer({
        chainId: n.chainId, from: n.owner, to, contract: n.contract, tokenId: n.tokenId, data: prep.tx.data,
      })
      log(sim.ok ? 'simulation OK — transfer would succeed' : `simulation FAILED — ${sim.revertReason}`, sim.ok ? 'ok' : 'err')

      const action = decodeCalldata(prep.tx.data, { to: prep.tx.to })
      const verdict = await evaluate({
        action, chainId: n.chainId, ownerAddress: n.owner,
        knownAddresses: (getAccounts?.() || []).map((a) => a.address),
        recipientIsNew: true, recipientCode, activeProofs,
        feeEth: prep.feeEstimate, nftName: n.name, simulation: sim,
      })

      const ok = await confirmSign({
        heading: `Send on ${chain.name}`,
        action: { ...action, plain: `You are transferring ${n.name}. Transfers are irreversible — the NFT leaves your wallet immediately once confirmed on-chain.` },
        verdict,
        balanceChanges: [
          { direction: 'out', what: held !== null ? `${prep.amount} × ${n.name}` : n.name, detail: `to ${to.slice(0, 10)}…` },
          { direction: 'out', what: `≈ ${Number(prep.feeEstimate).toFixed(6)} ETH network fee`, detail: chain.name },
          ...sim.changes.map((c) => ({ direction: 'out', what: c.what, detail: `${String(c.before).slice(0, 12)}… → ${String(c.after).slice(0, 12)}…` })),
        ],
        context: { account: n.owner, chainId: n.chainId, asset: n.name },
        meta: [
          { k: 'from', v: n.owner },
          { k: 'to', v: to },
          { k: 'collection', v: n.contract },
          { k: 'nonce', v: String(prep.tx.nonce) },
        ],
      })
      if (!ok) { log('cancelled'); sendBtn.disabled = false; return }

      log('CONFIRM the transaction on your KeepKey…', 'act')
      const hash = await signAndBroadcast(n, prep)
      recordBroadcast({
        hash, chainId: n.chainId, chainName: chain.name, kind: 'nft-transfer',
        asset: held !== null ? `${prep.amount} × ${n.name}` : n.name,
        from: n.owner, to, nonce: prep.tx.nonce, account: n.owner, accountIndex: n.ownerIndex,
      })
      refresh()
      log(`broadcast ${hash}`, 'ok')
      log(`track: ${chain.explorer}/tx/${hash}`)
      log('waiting for confirmation…')
      const receipt = await waitForReceipt(n.chainId, hash)
      settle(hash, receipt.status === 'success' ? 'success' : 'reverted', receipt.blockNumber)
      if (receipt.status === 'success') {
        log(`CONFIRMED in block ${receipt.blockNumber} — ${n.name} transferred. Rescan to update the gallery.`, 'ok')
      } else {
        log('transaction REVERTED on-chain — the NFT did not move', 'err')
      }
      refresh()
    } catch (e) {
      log('send failed: ' + e.message, 'err')
    }
    sendBtn.disabled = false
  })

  return el('div', { class: 'divider' },
    el('div', { class: 'boxtitle' }, 'Send ', el('span', { class: 'boxsub' }, '— hardware-signed transfer (moves the NFT!)')),
    el('label', {}, 'recipient'), input,
    amountInput ? el('label', {}, `amount (you hold ${held})`) : null,
    amountInput,
    el('div', { class: 'btnrow' }, sendBtn))
}
